document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("input[data-type-phone]").forEach(function(t){t.addEventListener("input",function(t){let e=t.target.value.replace(/\D/g,"");if((t.target.value.includes("+7")||e.length>0&&("8"===e[0]||e[0]>="0"&&e[0]<="6"||"9"===e[0]))&&(e="9"+e.substring(1)),e.length>0){let n="";e.length>=1&&(n+="("+e.substring(0,3)),e.length>=4&&(n+=") "+e.substring(3,6)),e.length>=7&&(n+="-"+e.substring(6,8)),e.length>=9&&(n+="-"+e.substring(8,10)),t.target.value=n}else t.target.value=""})})});